<template>
  <div class="relative w-full">
    <Input
      :id="id"
      class="pr-10"
      :type="isVisible ? 'text' : 'password'"
      :placeholder="placeholder"
      v-bind="componentField"
      :disabled="disabled"
      :autocomplete="autocomplete"
    />
    <span
      class="absolute end-0 inset-y-0 flex items-center justify-center px-3 cursor-pointer"
      @click="togglePasswordVisibility()"
    >
      <component :is="isVisible ? EyeOffIcon : EyeIcon" class="size-5 text-muted-foreground" />
    </span>
  </div>
</template>

<script setup lang="ts">
import { EyeIcon, EyeOffIcon } from 'lucide-vue-next';
import type { ComponentFieldBindingObject } from 'vee-validate';

interface Props {
  id: string;
  placeholder?: string;
  componentField: ComponentFieldBindingObject;
  autocomplete?: string;
  disabled?: boolean;
}

withDefaults(defineProps<Props>(), {
  placeholder: '',
  autocomplete: undefined,
  disabled: false,
});

const isVisible = ref<boolean>(false);

function togglePasswordVisibility() {
  isVisible.value = !isVisible.value;
}
</script>
